<?php
namespace App\Http\Controllers;use App\Core\Mcp\McpClient;use App\Models\McpServer;use Illuminate\Http\Request;
final class McpServerController extends Controller {public function index(){return view('mcp.index',['servers'=>McpServer::latest()->paginate(20)]);}public function create(){return view('mcp.form',['server'=>new McpServer(['transport'=>'http'])]);}public function store(Request $r){McpServer::create($this->data($r));return redirect()->route('mcp.index')->with('status',__('ui.saved'));}public function edit(McpServer $mcp){return view('mcp.form',['server'=>$mcp]);}public function update(Request $r,McpServer $mcp){$mcp->update($this->data($r,$mcp));return redirect()->route('mcp.index')->with('status',__('ui.saved'));}public function test(McpServer $mcp){try{$data=(new McpClient($mcp))->discover();return back()->with('status','MCP connected: '.($data['serverInfo']['name']??$mcp->name));}catch(\Throwable $e){return back()->with('error','MCP connection failed: '.$e->getMessage());}}public function destroy(McpServer $mcp){$mcp->delete();return back()->with('status',__('ui.deleted'));}private function data(Request $r,?McpServer $existing=null):array{$d=$r->validate(['name'=>'required|max:120','transport'=>'required|in:http','endpoint'=>'required|url|max:1000','token'=>'nullable|max:1000','protocol_version'=>'required|in:2025-11-25,2026-07-28','enabled'=>'nullable|boolean']);abort_unless(str_starts_with($d['endpoint'],'https://')||app()->environment('local'),422,'Remote MCP endpoints must use HTTPS.');$credentials=$existing?($existing->credentials??[]):[];if(!empty($d['token']))$credentials['token']=$d['token'];return ['name'=>$d['name'],'transport'=>$d['transport'],'endpoint'=>$d['endpoint'],'credentials'=>$credentials,'configuration'=>['protocol_version'=>$d['protocol_version']],'enabled'=>$r->boolean('enabled',true)];}}
